def story(toc=[]):
 a=[Spacer(1,3.4*cm),P('HOTEL MANAGEMENT SYSTEM','RptTitle'),Spacer(1,.4*cm),P('Project Report for BACSE202 Lab Component Project Assessment 8','RptCover'),Spacer(1,1*cm),P('Submitted by<br/><b>Shraddha Sidhan</b><br/>Registration Number: 25BDS0110<br/>B.Tech CSE - Data Science<br/>Academic Year: 2026-27','RptCover'),Spacer(1,1*cm),P('School of Computer Science and Engineering SCOPE<br/>Vellore Institute of Technology Vellore','RptCover'),PageBreak(),H('Table of Contents','')]
 a += [P(f'{n} {t}<font color="#112B46"> ........................................ {pg}</font>','RptToc') for n,t,pg in toc] or [P('Pagination is prepared in the final pass.')];a += [PageBreak()]
 data=[('1','Case Study 1','Hotels coordinate guests, rooms, employees, payments and chargeable services daily. Manual registers and disconnected spreadsheets make availability difficult to verify, encourage repeated entry and slow reporting. The Hotel Management System is a relational database solution for connecting these operations.'),('2','Abstract','This PostgreSQL 17 project models nine entities: GUEST, ROOM_TYPE, ROOM, BOOKING, PAYMENT, DEPARTMENT, EMPLOYEE, SERVICE and SERVICE_REQUEST. Primary and foreign keys preserve relationships; CHECK and UNIQUE constraints protect integrity. The design is normalized to Third Normal Form.'),('3','System Design','The system uses a user interface for transactions, an application layer for validation, and PostgreSQL storage. Modules cover guest and room master data, booking, payment, employee, departments, services and management reports. Relationships are represented with foreign keys and the booking-service association is recorded by SERVICE_REQUEST.'),('6','Introduction','Database management is central to hotel operations because each guest interaction is linked to room inventory, time, money and staff responsibility. A relational database lets authorised users locate a booking, assigned room, service requests and payments from the same controlled data set.'),('7','Background of the Project','Manual registers and spreadsheets can create duplicated entry, weak referential control and difficult audit trails. The proposed PostgreSQL design stores master facts once and uses foreign keys and domain constraints for transactions.'),('11','Conclusion','The nine-table design separates master information from transactions, enforces relationships and supports management reporting. Future enhancements can add online reservations, role-based access, invoices, audit logs and real-time housekeeping status.')]
 for n,t,x in data[:3]: a += [H(n,t),P(x)]
 a += [H('4','E R Diagram'),P('Figure 1 includes all nine entities, primary keys, foreign keys, relationship names and cardinalities. EMPLOYEE has the recursive manager relationship; SERVICE_REQUEST is the associative entity.'),ER(),P('Figure 1  Entity relationship diagram for the Hotel Management System','RptCap'),H('5','Workflow'),P('Booking proceeds only when a suitable room is available. Service requests are recorded during the stay; billing, payment and checkout complete the process.'),WF(),P('Figure 2  Hotel management workflow','RptCap')]
 for n,t,x in data[3:5]: a += [H(n,t),P(x)]
 a += [H('8','Hardware and Software Requirements'),TAB([['Component','Specification / Choice'],['Processor','Intel Core i3 or equivalent'],['Memory','4 GB RAM or higher'],['Storage','1 GB free disk space or higher'],['Operating system','Windows Linux or macOS'],['Database server','PostgreSQL 17'],['Language','SQL'],['Development tools','PostgreSQL client tools and text editor or IDE']],[4.6*cm,12.1*cm]),P('The project schema uses PostgreSQL types and constraints including NUMERIC, DATE, VARCHAR, keys and CHECK clauses.'),H('9','Description of Database Design'),H('9.1','Entity Summary',2),TAB([['Table','Purpose','Primary Key','References'],['GUEST','Guest contact identity','GUEST_ID','-'],['ROOM_TYPE','Room category price capacity','TYPE_ID','-'],['ROOM','Individual room status','ROOM_ID','TYPE_ID'],['BOOKING','Reservation and stay','BOOKING_ID','GUEST_ID ROOM_ID'],['PAYMENT','Payment against booking','PAYMENT_ID','BOOKING_ID'],['DEPARTMENT','Department data','DEPT_ID','-'],['EMPLOYEE','Employee hierarchy','EMP_ID','DEPT_ID MANAGER_ID'],['SERVICE','Service catalogue','SERVICE_ID','-'],['SERVICE_REQUEST','Services supplied','REQUEST_ID','BOOKING_ID SERVICE_ID EMP_ID']],[2.7*cm,5.2*cm,3*cm,5.8*cm]),H('9.2','Attributes Constraints and Relationships',2),P('GUEST has unique phone, email and identity-proof values. ROOM_TYPE uses positive price and capacity; ROOM accepts Available, Occupied or Maintenance. BOOKING connects guest and room, requires checkout after check-in, and restricts statuses. PAYMENT requires a positive amount. EMPLOYEE belongs to a department and may refer to another employee as manager. SERVICE_REQUEST connects booking, service and employee with a positive quantity.'),H('9.3','Normalization to Third Normal Form',2),P('<b>1NF:</b> attributes are atomic and every table has a primary key. <b>2NF:</b> non-key fields depend on the whole key. <b>3NF:</b> room type, department and service price facts reside in separate tables, preventing transitive dependencies and update anomalies.'),H('10','SQL Implementation'),P('The following listings preserve available project schema and sample data. No output screenshots are included because none were supplied, and no unexecuted query results are claimed.')]
 schema=(ROOT/'db/schema.sql').read_text(); seed=(ROOT/'db/seed.sql').read_text(); a += [H('10.1','CREATE TABLE with Constraints',2),CODE(schema),H('10.2','INSERT Statements Up To Five Sample Records Per Table',2),CODE(seed),H('10.3','DELETE and UPDATE Operations',2),CODE("DELETE FROM SERVICE_REQUEST WHERE REQUEST_ID=5;\nDELETE FROM PAYMENT WHERE PAYMENT_ID=5;\nDELETE FROM BOOKING WHERE BOOKING_ID=5;\nDELETE FROM ROOM WHERE ROOM_ID=5; DELETE FROM GUEST WHERE GUEST_ID=5;\nDELETE FROM SERVICE WHERE SERVICE_ID=5; DELETE FROM EMPLOYEE WHERE EMP_ID=5;\nDELETE FROM DEPARTMENT WHERE DEPT_ID=5; DELETE FROM ROOM_TYPE WHERE TYPE_ID=5;\nUPDATE GUEST SET CITY='Bengaluru' WHERE GUEST_ID=1;\nUPDATE ROOM_TYPE SET BASE_PRICE=2600 WHERE TYPE_ID=1; UPDATE ROOM SET ROOM_STATUS='Occupied' WHERE ROOM_ID=1;\nUPDATE BOOKING SET BOOKING_STATUS='Checked-In' WHERE BOOKING_ID=3; UPDATE PAYMENT SET PAY_MODE='Card' WHERE PAYMENT_ID=1;\nUPDATE DEPARTMENT SET LOCATION='Ground Floor' WHERE DEPT_ID=1; UPDATE EMPLOYEE SET SALARY=92000 WHERE EMP_ID=1;\nUPDATE SERVICE SET SERVICE_PRICE=550 WHERE SERVICE_ID=1; UPDATE SERVICE_REQUEST SET QUANTITY=3 WHERE REQUEST_ID=1;"),H('10.4','SELECT Functions Aggregate GROUP BY and HAVING',2),CODE("SELECT * FROM GUEST;\nSELECT GUEST_NAME, UPPER(CITY), LENGTH(GUEST_NAME) FROM GUEST;\nSELECT COUNT(*) FROM GUEST; SELECT AVG(SALARY), MAX(SALARY) FROM EMPLOYEE;\nSELECT PAY_MODE, COUNT(*), SUM(AMOUNT) FROM PAYMENT GROUP BY PAY_MODE;\nSELECT d.DEPT_NAME, AVG(e.SALARY) FROM DEPARTMENT d JOIN EMPLOYEE e ON e.DEPT_ID=d.DEPT_ID GROUP BY d.DEPT_NAME HAVING AVG(e.SALARY)>50000;"),H('10.5','Subqueries JOIN Queries and Management Information',2),CODE("SELECT EMP_NAME, SALARY FROM EMPLOYEE WHERE SALARY>(SELECT AVG(SALARY) FROM EMPLOYEE);\nSELECT b.BOOKING_ID,g.GUEST_NAME,r.ROOM_NO,rt.TYPE_NAME FROM BOOKING b JOIN GUEST g ON g.GUEST_ID=b.GUEST_ID JOIN ROOM r ON r.ROOM_ID=b.ROOM_ID JOIN ROOM_TYPE rt ON rt.TYPE_ID=r.TYPE_ID;\nSELECT rt.TYPE_NAME,COUNT(b.BOOKING_ID),COALESCE(SUM(b.TOTAL_AMOUNT),0) FROM ROOM_TYPE rt LEFT JOIN ROOM r ON r.TYPE_ID=rt.TYPE_ID LEFT JOIN BOOKING b ON b.ROOM_ID=r.ROOM_ID AND b.BOOKING_STATUS<>'Cancelled' GROUP BY rt.TYPE_ID,rt.TYPE_NAME;"),H('11','Conclusion'),P(data[-1][2]),H('12','References'),P('[1] PostgreSQL Global Development Group, <i>PostgreSQL 17 Documentation</i>, https://www.postgresql.org/docs/17/ (accessed 12 October 2026).'),P('[2] R. Elmasri and S. B. Navathe, <i>Fundamentals of Database Systems</i>, 7th ed., Pearson, 2016.'),P('[3] A. Silberschatz, H. F. Korth and S. Sudarshan, <i>Database System Concepts</i>, 7th ed., McGraw Hill, 2019.'),P('[4] PostgreSQL Global Development Group, <i>SQL Language Documentation</i>, https://www.postgresql.org/docs/current/sql.html (accessed 12 October 2026).')]
 return a
