 for x in ['Project Report for BACSE202 Lab Component Project Assessment 8','','Shraddha Sidhan','Registration Number: 25BDS0110','B.Tech CSE - Data Science','Academic Year: 2026-27','','School of Computer Science and Engineering SCOPE','Vellore Institute of Technology Vellore']: z=d.add_paragraph(x);z.alignment=WD_ALIGN_PARAGRAPH.CENTER
